import{_ as a,C as o,o as s,c as n,j as r,a as i,E as l,a6 as u}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Failure inbox","description":"Home's failure inbox: the open failure clusters you still owe a decision, in queues, triaged from the row, the keyboard or a bulk bar.","frontmatter":{"title":"Failure inbox","description":"Home's failure inbox: the open failure clusters you still owe a decision, in queues, triaged from the row, the keyboard or a bulk bar.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/failure-inbox.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/failure-inbox.html"}],["meta",{"property":"og:title","content":"Failure inbox | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Home's failure inbox: the open failure clusters you still owe a decision, in queues, triaged from the row, the keyboard or a bulk bar."}]]},"headers":[],"relativePath":"features/failure-inbox.md","filePath":"features/failure-inbox.md","lastUpdated":1795554528000}`),h={name:"features/failure-inbox.md"};function d(c,e,g,f,m,p){const t=o("Needs");return s(),n("div",null,[e[0]||(e[0]=r("h1",{id:"failure-inbox",tabindex:"-1"},[i("Failure inbox "),r("a",{class:"header-anchor",href:"#failure-inbox","aria-label":'Permalink to "Failure inbox"'},"​")],-1)),l(t,{reporter:""}),e[1]||(e[1]=u('<p>The <strong>Failure inbox</strong> on Home lists the open <a href="./failure-clusters.html">failure clusters</a> you still owe a decision, sorts them into queues, and lets you triage each one from its row or the keyboard. What a cluster is, how failures join one and whether its fix worked is on <a href="./failure-clusters.html">Failure clusters</a>.</p><h2 id="what-it-lists" tabindex="-1">What it lists <a class="header-anchor" href="#what-it-lists" aria-label="Permalink to &quot;What it lists&quot;">​</a></h2><p>The inbox lists up to 50 open clusters of the projects you can see, most recently seen first. Each row shows the cluster&#39;s <strong>headline</strong>, its <strong>top clue</strong>, its <strong>owner or assignee</strong>, the <strong>affected tests</strong>, when it was <strong>last seen</strong>, and exceptional <strong>badges</strong> only (a regression on the default branch, <em>snoozed, back</em>).</p><ul><li><strong>Local runs.</strong> A cluster seen only in developers&#39; local runs, in a project that runs in CI, stays out; <strong>Show them</strong> lists them, marked <em>local runs only</em>.</li><li><strong>Environment incidents.</strong> The clusters a run flagged as an <a href="./environment-incidents.html#what-a-flagged-run-changes">environment incident</a> opened are one row for that run.</li><li><strong>Snoozed clusters</strong> are out of every queue until their <a href="./failure-clusters.html#snoozing">snooze</a> ends.</li></ul><h3 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h3><p>Each queue has a live count and is shareable as <code>?queue=</code>:</p><ul><li><strong>All open</strong>: every open cluster not snoozed.</li><li><strong>New</strong>: first seen, or seen again, since your previous browser session (kept per browser).</li><li><strong>Mine</strong>: assigned to you, or owned by you (<a href="./failure-clusters.html#owners-and-assignees">owners and assignees</a>).</li><li><strong>Needs ticket</strong>: untracked default-branch clusters older than the binding&#39;s age (2 days by default; see <a href="./issue-tracking.html">issue tracking</a>).</li><li><strong>Regressions</strong>: regressed on the default branch, failing there still.</li><li><strong>Fix didn&#39;t hold</strong>: a fix landed, then <a href="./failure-clusters.html#did-the-fix-work">regressed</a>.</li><li><strong>Quarantine ready</strong>: <a href="./flaky-tests.html#quarantine-with-a-way-out">quarantined</a>, and the tests stopped failing.</li><li><strong>Merge suggestions</strong>: in a pending <a href="./ai-diagnosis.html#semantic-merging-optional">merge suggestion</a>.</li></ul><h3 id="triage-from-the-row-or-the-keyboard" tabindex="-1">Triage from the row or the keyboard <a class="header-anchor" href="#triage-from-the-row-or-the-keyboard" aria-label="Permalink to &quot;Triage from the row or the keyboard&quot;">​</a></h3><p>Open, resolve, ignore, quarantine, assign, snooze, link a known issue or create a tracker issue from the row, by mouse or <a href="/reference/keyboard-shortcuts.html#failure-inbox">key</a>; <code>x</code> selects rows for a <strong>bulk bar</strong>. Resolve, ignore, quarantine, assign and snooze need the Maintainer role or above on the project; linking a known issue and creating a tracker issue need Contributor.</p><p>Resolve, ignore, snooze and assign on one row can be undone for a few seconds. A known issue pins a URL; with an <a href="/operate/integrations.html">issue tracker</a> bound, Jira links unfurl and stay in sync (<a href="./issue-tracking.html">issue tracking</a>).</p><h2 id="from-an-ai-agent" tabindex="-1">From an AI agent <a class="header-anchor" href="#from-an-ai-agent" aria-label="Permalink to &quot;From an AI agent&quot;">​</a></h2><p>Over the <a href="/features/mcp.html">MCP server</a>, <code>list_open_clusters</code> takes the same <code>queue</code>, and each triage action has a <a href="/reference/mcp-tools.html">tool</a>: <code>triage_cluster</code>, <code>decide_merge_suggestion</code>, <code>link_issue</code> and <code>unlink_issue</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./failure-clusters.html">Failure clusters</a>: how failures are grouped, the cluster page, and whether the fix worked</li><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: a red run collapsed into causes</li><li><a href="/reference/keyboard-shortcuts.html#failure-inbox">Keyboard shortcuts</a>: every key of the inbox</li><li><a href="./issue-tracking.html">Issue tracking</a>: the tickets behind <strong>Needs ticket</strong> and a known issue</li></ul>',14))])}const w=a(h,[["render",d]]);export{k as __pageData,w as default};
